import overcrow from './overcrow.js';
const response = await overcrow.fetch('https://api.warframe.market/v2/items');
if (!response.ok) throw new Error('Catalog unavailable');
const catalog = await response.json();

let count = 0;
const output = document.querySelector('#count');
document.querySelector('#increment').addEventListener('click', () => {
  output.textContent = String(++count);
});

import overcrow from './overcrow.js';
if (overcrow.runtime.role === 'unavailable') {
  document.querySelector('#status').textContent = 'OverCrow services are not connected.';
}

import overcrow from './overcrow.js';
const status = document.querySelector('#status');
try {
  const response = await overcrow.fetch('https://api.example.com/v2/items');
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const data = await response.json();
  status.textContent = data.items?.length ? data.items.length + ' items' : 'No items';
} catch (error) {
  status.textContent = 'Items are unavailable. Try again later.';
}

import overcrow from './overcrow.js';
const snapshot = await overcrow.game.snapshot();
document.querySelector('#session').textContent =
  snapshot.running ? 'Game running' : 'No active game';

import overcrow from './overcrow.js';
function render(snapshot) {
  const ms = snapshot.sessionElapsedMs;
  document.querySelector('#duration').textContent =
    typeof ms === 'number' ? Math.floor(ms / 60000) + ' min' : 'Session unavailable';
}
const stop = overcrow.game.onSnapshot(render);
render(await overcrow.game.snapshot());
// Call stop() when the component is removed.

import overcrow from './overcrow.js';
const state = { count: 0 };
overcrow.runtime.onMessage(async message => {
  if (!message || typeof message !== 'object') return;
  if (message.type === 'increment') state.count += 1;
  if (message.type === 'hello' || message.type === 'increment') {
    await overcrow.runtime.send({ type: 'state', count: state.count });
  }
});

import overcrow from './overcrow.js';
overcrow.runtime.onMessage(message => {
  if (message?.type !== 'state' || !Number.isSafeInteger(message.count)) return;
  document.querySelector('#count').textContent = String(message.count);
});
await overcrow.runtime.send({ type: 'hello' });
document.querySelector('#increment').addEventListener('click', () => {
  overcrow.runtime.send({ type: 'increment' }).catch(console.error);
});

const stop = overcrow.lifecycle.onVisibility(visible => {
  document.body.dataset.visible = String(visible);
  // Pause animation or unnecessary work while hidden.
});

function readPreferences() {
  try {
    const value = JSON.parse(localStorage.getItem('preferences.v1') ?? '{}');
    return { compact: value?.compact === true };
  } catch { return { compact: false }; }
}
function savePreferences(preferences) {
  try { localStorage.setItem('preferences.v1', JSON.stringify(preferences)); return true; }
  catch { return false; }
}

import overcrow from './overcrow.js';
const messages = { en: { ready: 'Ready' }, fr: { ready: 'Prêt' } };
function render(locale) {
  document.querySelector('#status').textContent = (messages[locale] ?? messages.en).ready;
}
const stop = overcrow.locale.onChanged(render);
render(await overcrow.locale.getCurrent());

import overcrow from './overcrow.js';
document.querySelector('#copy').addEventListener('click', async () => {
  const status = document.querySelector('#status');
  try {
    await overcrow.clipboard.writeText('Hello from OverCrow');
    status.textContent = 'Copied';
  } catch {
    status.textContent = 'Copy denied. Try again in interactive mode.';
  }
});
